$ErrorActionPreference = 'Stop'

# Generated by RoleCraft - https://rolecraft.omhinge.cloud
# Creates a permissions policy and attaches it to an existing IAM group.

$RoleName = 'analytics-reader'
$PrincipalName = 'analytics-team'

# Permissions policy
[System.IO.File]::WriteAllText((Join-Path $PWD.ProviderPath 'policy.json'), @'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "S3ListReadList",
      "Effect": "Allow",
      "Action": "s3:ListBucket",
      "Resource": "arn:aws:s3:::data-lake",
      "Condition": {
        "StringLike": {
          "s3:prefix": [
            "reports/",
            "reports/*"
          ]
        }
      }
    },
    {
      "Sid": "S3ListReadObjects",
      "Effect": "Allow",
      "Action": [
        "s3:GetObject",
        "s3:GetObjectVersion"
      ],
      "Resource": "arn:aws:s3:::data-lake/reports/*"
    }
  ]
}
'@)

$PolicyArn = aws iam create-policy "--policy-name=${RoleName}-policy" --policy-document file://policy.json --description 'Created with RoleCraft' --query Policy.Arn --output text --no-cli-pager
if ($LASTEXITCODE -ne 0) { throw "aws failed: create-policy" }
aws iam attach-group-policy "--group-name=$PrincipalName" "--policy-arn=$PolicyArn" --no-cli-pager
if ($LASTEXITCODE -ne 0) { throw "aws failed: attach-group-policy" }

Write-Output "Attached the policy to group $PrincipalName."
